  "his-bce-ce-bp": {
    "title": "BCE, CE and BP",
    "card": [
      [
        "BCE",
        "Before the Common Era. These dates come before the year 1 CE. They count down towards it, so 500 BCE is earlier than 200 BCE."
      ],
      [
        "CE",
        "Common Era. CE dates start at the year 1 and count up, so 200 CE is earlier than 500 CE. There is no year 0: 1 BCE is followed by 1 CE."
      ],
      [
        "BP",
        "Before present. Archaeologists use it to count years back from the present, which is fixed at 1950 CE. A larger BP number means an older date."
      ],
      "BCE and CE dates are counted from the start of the Common Era. BP dates are counted back from 1950."
    ],
    "remember": "BCE numbers shrink as time goes on, CE numbers grow, and BP counts back from 1950.",
    "a": {
      "q": "Put these dates in time order. Which one comes first?",
      "opts": ["750 BCE", "250 BCE", "50 CE", "400 CE"],
      "why": "BCE dates count down towards 1 CE, so 750 BCE is further back in time than 250 BCE, and every BCE date comes before every CE date. 250 BCE is tempting because 250 is a smaller number, but BCE numbers get smaller as time moves forward.",
      "clue": "In BCE, a bigger number is further back in time."
    },
    "b": {
      "d": 3,
      "q": "A museum label says charcoal from an old campfire is 8,000 years BP. What does this date mean?",
      "opts": [
        "8,000 years before 1950",
        "8,000 years after the year 1",
        "8,000 years before the year 1",
        "The year 8,000 in the Common Era"
      ],
      "why": "BP means before present, and archaeologists fix the present at 1950, so the charcoal is 8,000 years older than 1950. Counting back from the year 1 is how BCE works, not BP.",
      "clue": "What year do archaeologists treat as the present?"
    }
  },
